const NS="dicebox-campaign-helper";
if(!game?.ready||game.world?.id!=="cabin-in-the-ashen-veil"||
 game.version!=="14.367"||scene?.id!=="CAVEXT06Scene001"||
 region?.id!=="CAVB6E433D528867")return;
const flag=k=>region.getFlag(NS,k);
const state=flag("cavLateGreenhouseMix")?.status??"none";
if(event?.name==="behaviorViewed"&&!game.user?.isGM){
  const key="__CAV_B17_GREENHOUSE_"+region.id;
  if(globalThis[key]?.handler&&canvas?.stage)canvas.stage.off("pointertap",globalThis[key].handler);
  const handler=async e=>{
    if(!canvas?.ready||canvas.scene?.id!=="CAVEXT06Scene001"||game.user?.isGM)return;
    const pt=canvas.stage.toLocal(e.global);
    if(!region.testPoint({x:pt.x,y:pt.y,elevation:0})||globalThis[key+"_OPEN"])return;
    globalThis[key+"_OPEN"]=true;
    try{
      const description=state==="done"?
       "The Greenhouse workstation has already produced its original Plant Killer flask.":
       "The old Greenhouse controls connect to the restored Waterworks. The original quest Lye is the only required ingredient. The machine will not operate without genuine Waterworks and Soap Case provenance.";
      await foundry.applications.api.DialogV2.prompt({
        window:{title:"Greenhouse — mixing controls"},content:"<p>"+description+"</p>",
        ok:{label:"Close",callback:()=>true},rejectClose:false});
    }finally{globalThis[key+"_OPEN"]=false;}
  };
  if(canvas?.stage){canvas.stage.on("pointertap",handler);globalThis[key]={handler};}
  return;
}
if(["behaviorUnviewed","behaviorDeactivated"].includes(event?.name)){
  const key="__CAV_B17_GREENHOUSE_"+region.id;
  if(globalThis[key]?.handler&&canvas?.stage)canvas.stage.off("pointertap",globalThis[key].handler);
  delete globalThis[key];return;
}
if(!["tokenMoveIn","tokenMoveWithin"].includes(event?.name)||!
 (game.user?.isGM&&game.users?.activeGM?.id===game.user.id))return;
const datum=event.data?.token?.document??event.data?.token;
const token=scene.tokens.get(datum?.id??event.data?.tokenId);
if(!token||token.hidden||!token.actor||token.actor.type!=="character")return;
const actor=token.actor;
const owners=game.users.contents.filter(u=>u.active&&!u.isGM&&actor.testUserPermission(u,"OWNER"));
const sender=event.userId??event.data?.userId??null;
const player=sender?owners.find(u=>u.id===sender):(owners.length===1?owners[0]:null);
if(!player)return;
const center={x:token.x+token.width*scene.grid.size/2,y:token.y+token.height*scene.grid.size/2,elevation:0};
if(!region.testPoint(center))return;
if(state!=="none"||flag("cavLatePlantKillerClaim"))return;
const lye=game.items.get("vDR4cJU35iODR6gh"),
      result=game.items.get("YNWpGEGB17mqDFWe");
if(!lye||lye.uuid!=="Item.vDR4cJU35iODR6gh"||lye.name!=="Lye"||
 lye.type!=="loot"||lye.getFlag(NS,"cabinPuzzleItem")?.status!=="GM_LIBRARY_ONLY"||
 !result||result.uuid!=="Item.YNWpGEGB17mqDFWe"||
 result.name!=="Plant Killer"||result.type!=="loot"||
 result.getFlag(NS,"cabinPuzzleItem")?.status!=="GM_LIBRARY_ONLY")return;
if(game.actors.contents.some(a=>a.items.some(i=>i.name===result.name||
 i.getFlag(NS,"cavLatePlantKillerSourceUuid")===result.uuid)))return;
// WATERWORKS, not Pond/Bath Sluice, is required. The actual native authority
// remains in the original Aqueduct Waterworks Annex's OWN ledger.
const annex=game.scenes.get("CAVAQ01Scene0001")?.regions.get("kmPmr5ijLCEOJNk3");
const restored=annex?.getFlag(NS,"cavWaterworksRestore");
if(restored?.status!=="done"||restored?.reverifiedFromOriginalWaterworks!==true||
 restored?.greenhouseSprinklerFlowRestored!==true||
 restored?.originalAqueductSceneId!=="CAVAQ01Scene0001")return;
// Lye needs a legitimate claim from the original Bathhouse BATH-02 Soap Case,
// rather than a generic item of the same type.
const lyeInstance=actor.items.find(i=>i.name==="Lye"&&i.type==="loot"&&
 i.getFlag(NS,"cavLateLyeSourceUuid")==="Item.vDR4cJU35iODR6gh"&&
 Number(i.system?.quantity??0)>0);
if(!lyeInstance)return;
const originUuid=lyeInstance.getFlag(NS,"cavLateLyeOriginRegionUuid");
if(typeof originUuid!=="string")return;
const root=/^Scene\.([^.]+)\.Region\.([^.]+)$/.exec(originUuid);
if(!root||!["CAVBATHScene0001","8yLMRDvxyw58dydh"].includes(root[1]))return;
const soapScene=game.scenes.get(root[1]),soapRegion=soapScene?.regions.get(root[2]);
const soap=soapRegion?.getFlag(NS,"cavLateSoapCase");
const award=soapRegion?.getFlag(NS,"cavLateSoapLyeClaim");
if(!soapScene||!soapRegion||soap?.status!=="unlocked"||
 soap?.canonCode!=="BATH-02"||award?.status!=="done"||
 award?.actorId!==actor.id||award?.originalLyeSourceUuid!==lye.uuid||
 award?.embeddedItemId!==lyeInstance.id)return;
const gate="__CAV_B17_MIXBUSY_"+region.id;if(globalThis[gate])return;
globalThis[gate]=true;
try{
 const ok=await foundry.applications.api.DialogV2.confirm({
  window:{title:"Greenhouse — original Plant Killer"},
  content:"<p>The original Waterworks has been restored, and the character carries authenticated Lye from the Bathhouse Soap Case. Produce the one original Plant Killer flask?</p><p>No other reagent is required. Lye will NOT be consumed until the owner settles that rule. Confirm only after the player's deliberate action.</p>",
  yes:{label:"Approve production"},no:{label:"Cancel",callback:()=>false},rejectClose:false});
 if(!ok)return;
 // Recheck state after the asynchronous dialog. Do not race with other GM events.
 if(flag("cavLateGreenhouseMix")||flag("cavLatePlantKillerClaim"))return;
 await region.setFlag(NS,"cavLateGreenhouseMix",{status:"reserved",actorId:actor.id,
   originalLyeUuid:lye.uuid,originalWaterworksRegionUuid:annex.uuid,
   originalSoapCaseRegionUuid:soapRegion.uuid});
 if(region.getFlag(NS,"cavLateGreenhouseMix")?.status!=="reserved")throw Error("Reservation uncertain");
 const fresh=result.toObject();delete fresh._id;
 fresh.flags={...fresh.flags,[NS]:{...fresh.flags?.[NS],
   cavLatePlantKillerSourceUuid:result.uuid,
   cavLatePlantKillerOriginRegionUuid:region.uuid}};
 const made=await actor.createEmbeddedDocuments("Item",[fresh]);
 const embedded=made?.[0]&&actor.items.get(made[0].id);
 if(made?.length!==1||!embedded||
   embedded.getFlag(NS,"cavLatePlantKillerSourceUuid")!==result.uuid)
     throw Error("Original Plant Killer grant uncertain; reserved state retained");
 await region.setFlag(NS,"cavLatePlantKillerClaim",{status:"done",sourceUuid:result.uuid,
   actorId:actor.id,embeddedItemId:embedded.id});
 await region.setFlag(NS,"cavLateGreenhouseMix",{status:"done",actorId:actor.id,
   sourceUuid:result.uuid,lyeConsumed:false});
 try{await ChatMessage.create({speaker:{alias:"Greenhouse Workstation"},
  whisper:[player.id],content:"<p>You have produced the original Plant Killer flask.</p>"})}
 catch(e){console.warn("[CAV B17] Greenhouse grant committed; whisper failed",e);}
}catch(err){console.error("[CAV B17] Partial Greenhouse source transaction; RECONCILE; no replay",err)}
finally{globalThis[gate]=false}

// Roof Chimney Clock / CAV owner-approved handless artwork v001.
// Player click-to-inspect: NO inventory mutation, reward, or world flags are written here.
const SCENE='LhtyO17QenuCExsb',RID='CAVROOFCLOCKR001',NS='dicebox-campaign-helper';
const ART='worlds/cabin-in-the-ashen-veil/assets/puzzle-closeups/roof-clock-handless-owner-approved-preview-320-v001.avif';
const SLOT='__CAV_ROOFCLOCK_POINTER_v001',MODAL='__CAV_ROOFCLOCK_MODAL_v001';
if(game.world?.id!=='cabin-in-the-ashen-veil'||game.version!=='14.367'||scene?.id!==SCENE||region?.id!==RID)return;
const ev=event?.name;
if(ev==='behaviorUnviewed'||ev==='behaviorDeactivated'){
 const old=globalThis[SLOT];if(old?.handler&&canvas?.stage)canvas.stage.off('pointertap',old.handler);
 delete globalThis[SLOT];return;
}
if(ev!=='behaviorViewed'||game.user?.isGM)return;
const previous=globalThis[SLOT];if(previous?.handler&&canvas?.stage)canvas.stage.off('pointertap',previous.handler);
const handler=async e=>{
 if(!canvas?.ready||canvas.scene?.id!==SCENE||game.user?.isGM||(e.button!==undefined&&e.button!==0))return;
 const point=canvas.stage.toLocal(e.global);
 if(!region.testPoint({x:point.x,y:point.y,elevation:0}))return;
 if(globalThis[MODAL])return;
 globalThis[MODAL]=true;
 try{
  const tokens=canvas.tokens?.controlled?.filter(t=>t.actor?.testUserPermission(game.user,'OWNER'))||[];
  const doc=tokens.length===1?tokens[0].document:null,actor=doc?.actor||null;
  // UI-only proof: original DONE claim and exact embedded Actor Item must agree.
  // The elected GM still performs the authoritative global uniqueness checks.
  const hourClaim=game.scenes.get('CAVHG06GreatRoom')?.regions.get('MrWgTyGg0d0DI53Q')?.getFlag(NS,'cavGrandfatherClockHourHandClaim');
  const minuteClaim=game.scenes.get('nyF5EX0JiEu23C3p')?.regions.get('UtXhS68vd1czWfTG')?.getFlag(NS,'cavAtticMinuteHandClaim');
  const hasHour=!!actor&&hourClaim?.status==='done'&&hourClaim.actorId===actor.id&&hourClaim.sourceUuid==='Item.HVZnNaV2SxNWck6H'&&
   actor.items.some(i=>i.id===hourClaim.embeddedItemId&&i.name==='Grandfather Clock Hour Hand'&&
    i.getFlag(NS,'cavGrandfatherClockRewardSourceUuid')==='Item.HVZnNaV2SxNWck6H'&&
    i.getFlag(NS,'cavGrandfatherClockRewardRegionUuid')==='Scene.CAVHG06GreatRoom.Region.MrWgTyGg0d0DI53Q');
  const hasMinute=!!actor&&minuteClaim?.status==='done'&&minuteClaim.actorId===actor.id&&minuteClaim.itemUuid==='Item.smvovibxtjJ9NW56'&&
   actor.items.some(i=>i.id===minuteClaim.embeddedItemId&&i.name==='Attic Clock Minute Hand'&&
    i.getFlag(NS,'cavAtticLootSourceUuid')==='Item.smvovibxtjJ9NW56'&&
    i.getFlag(NS,'cavAtticLootRegionUuid')==='Scene.nyF5EX0JiEu23C3p.Region.UtXhS68vd1czWfTG');
  // Match elected GM's original 400px clock-center reach restriction.
  const rect=region.shapes?.[0],grid=scene.grid?.size;
  const near=!!doc&&!!rect&&Number.isFinite(grid)&&
   Math.hypot(doc.x+doc.width*grid/2-(rect.x+rect.width/2),doc.y+doc.height*grid/2-(rect.y+rect.height/2))<=400;
  const canEngage=hasHour&&hasMinute&&near;
  const solved=region.getFlag(NS,'cavRoofClockClaim')?.status==='done';
  const id='cav-roof-clock-panel-v001';
  let opts='<option value="">— Hour —</option>';for(let n=1;n<=12;n++)opts+='<option value="'+n+'">'+n+'</option>';
  let mins='<option value="">— Minute —</option>';for(let n=0;n<60;n+=5)mins+='<option value="'+n+'">'+String(n).padStart(2,'0')+'</option>';
  const status=solved?'The clock has already yielded its gear.':!doc?'The distant clock face seems impossible to examine from here.':!near?'From here, the worn clock face is difficult to examine.':(!hasHour||!hasMinute)?'The old clock face remains bare; the workings within are silent.':'Two worn fittings mark the center of the clock face.';
  const content='<div id="'+id+'" style="max-width:600px;margin:auto;text-align:center">'+
   '<img src="'+ART+'" alt="Approved close-up of the rooftop clock with both hands absent" style="display:block;max-width:100%;max-height:59vh;margin:auto;border:1px solid #80664b;border-radius:4px"/>'+
   '<p style="margin:0.8rem 0">'+status+'</p>'+
   (canEngage&&!solved?'<div style="display:flex;justify-content:center;gap:0.65rem"><label>Hour hand<br/><select id="cav-roof-hour">'+opts+'</select></label><label>Minute hand<br/><select id="cav-roof-minute">'+mins+'</select></label></div><small>A circle of faded numerals surrounds the empty clock face.</small>':'')+
   '</div>';
  await foundry.applications.api.DialogV2.prompt({
   window:{title:'The Roof Chimney Clock'},content,
   ok:{label:canEngage&&!solved?'Engage Mechanism':'Close',callback:async()=>{
    if(!canEngage||solved||!doc)return true;
    const hour=document.getElementById('cav-roof-hour')?.value,minute=document.getElementById('cav-roof-minute')?.value;
    if(!hour||minute==null||minute===''){ui.notifications?.warn('The mechanism stirs but fails to catch.');return false;}
    const gm=game.users.activeGM;
    if(!gm?.active){ui.notifications?.warn('The clock mechanism is unavailable without the GM.');return false;}
    await ChatMessage.create({
     content:'<p>You adjust the hands of the roof clock and listen for the mechanism.</p>',
     whisper:[gm.id,game.user.id],
     flags:{[NS]:{cavRoofClockAttempt:{version:1,action:'roof-clock-attempt',sceneId:SCENE,regionId:RID,tokenId:doc.id,hour:Number(hour),minute:Number(minute)}}}
    });
    return true;
   }},rejectClose:false
  });
 }catch(err){console.warn('[CAV roof clock] player visual failed',err);}
 finally{globalThis[MODAL]=false;}
};
if(canvas?.stage){canvas.stage.on('pointertap',handler);globalThis[SLOT]={handler};}

// First Chest 024: player click or player-controlled token entry opens player macro.
// Existing Scene/Region are not moved, recolored, or resized.
const sid = 'CAVHG06GreatRoom';
const rid = 'ibN7AGsY4AlG582M';
const macroId = 'CAVCHEST024MAC01';
const callbackKey = '__CAV_FIRST_CHEST_024_POINTER_V1__';
const isHere = scene?.id === sid && region?.id === rid && canvas.scene?.id === sid;
if (!isHere || game.world?.id !== 'cabin-in-the-ashen-veil') return;
const existing = globalThis[callbackKey];
if (['behaviorUnviewed','behaviorDeactivated'].includes(event?.name)) {
  if (existing?.handler && canvas.stage) canvas.stage.off('pointertap', existing.handler);
  delete globalThis[callbackKey];
  return;
}
const opened = () => game.messages.contents.some(m => m.getFlag('dicebox-campaign-helper','cavFirstChest024')?.status==='unlocked');
const start = async () => {
  if (opened() || globalThis.__CAV_CHEST_024_DIALOG_BUSY__) return;
  const macro = game.macros.get(macroId);
  if (!macro?.canUserExecute(game.user)) {
    ui.notifications.warn('This chest lock is unavailable to your account.');
    return;
  }
  globalThis.__CAV_CHEST_024_DIALOG_BUSY__ = true;
  try {await macro.execute()}
  finally {globalThis.__CAV_CHEST_024_DIALOG_BUSY__ = false}
};
if (event?.name === 'behaviorViewed') {
  // The viewer client owns the actual dialog. The GM is not a required operator.
  if (existing?.handler && canvas.stage) canvas.stage.off('pointertap',existing.handler);
  const handler = async pointer => {
    if (!canvas.ready || canvas.scene?.id!==sid) return;
    if (pointer.button !== undefined && pointer.button !== 0) return;
    const point=canvas.stage.toLocal(pointer.global);
    if (!region.testPoint({x:point.x,y:point.y,elevation:0})) return;
    await start();
  };
  canvas.stage.on('pointertap',handler);
  globalThis[callbackKey]={handler,sceneId:sid,regionId:rid};
}
if (event?.name === 'tokenMoveIn' && !game.user.isGM) {
  const candidate=event.data?.token?.document ?? event.data?.token;
  const token=scene.tokens.get(candidate?.id??event.data?.tokenId);
  if (!token?.actor || !token.actor.testUserPermission(game.user,'OWNER')) return;
  const initiatingId=event.user?.id??event.userId??null;
  if (initiatingId && initiatingId!==game.user.id) return;
  await start();
}

// Sophia bookcase: owner-approved zoom; storybook titles and slot assignments NOT assumed.
const SCENE='CAVHU05Scene0001',RID='CAVB994894A7432F',SLOT='__CAV_SOPHIA_BOOKS_INSPECT_v001';
const IMG='worlds/cabin-in-the-ashen-veil/assets/puzzle-closeups/sophia-bookcase-approved-crop-v001.png';
if(game.world?.id!=='cabin-in-the-ashen-veil'||game.version!=='14.367'||scene?.id!==SCENE||region?.id!==RID)return;
const ev=event?.name,prior=globalThis[SLOT];
if(ev==='behaviorUnviewed'||ev==='behaviorDeactivated'){
 if(prior?.handler&&canvas?.stage)canvas.stage.off('pointertap',prior.handler);
 delete globalThis[SLOT];return;
}
if(ev!=='behaviorViewed'||game.user?.isGM)return;
if(prior?.handler&&canvas?.stage)canvas.stage.off('pointertap',prior.handler);
const handler=async e=>{
 if(!canvas?.ready||canvas.scene?.id!==SCENE||game.user.isGM||(e.button!==undefined&&e.button!==0))return;
 const pt=canvas.stage.toLocal(e.global);
 if(!region.testPoint({x:pt.x,y:pt.y,elevation:0}))return;
 if(globalThis[SLOT+'_MODAL'])return;globalThis[SLOT+'_MODAL']=true;
 try{await foundry.applications.api.DialogV2.prompt({
  window:{title:'Sophia\u2019s Bookcase'},
  content:'<figure style="max-width:570px;margin:auto;text-align:center"><img src="'+IMG+'" alt="Close-up of the books and keepsakes on Sophia\u2019s bookcase" style="display:block;max-width:100%;max-height:67vh;margin:auto"/><figcaption style="font-style:italic;margin:0.6rem">The shelves hold stories and keepsakes arranged with care. Several familiar bindings catch your eye.</figcaption></figure>',
  ok:{label:'Close',callback:()=>true},rejectClose:false
 });}finally{globalThis[SLOT+'_MODAL']=false;}
};
if(canvas?.stage){canvas.stage.on('pointertap',handler);globalThis[SLOT]={handler};}
